CREATE TABLE IF NOT EXISTS ap_users (id SERIAL PRIMARY KEY, email TEXT NOT NULL UNIQUE, nombre TEXT NOT NULL, user_token TEXT NOT NULL UNIQUE, rol TEXT NOT NULL DEFAULT 'editor', activo BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_ap_users_token ON ap_users(user_token) WHERE activo = TRUE;
CREATE TABLE IF NOT EXISTS ap_skills (id SERIAL PRIMARY KEY, nombre TEXT NOT NULL UNIQUE, descripcion TEXT, workflow_id TEXT, activo BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ap_chats (id SERIAL PRIMARY KEY, session_id TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL REFERENCES ap_users(id), skill_id INTEGER NOT NULL REFERENCES ap_skills(id), titulo TEXT, estado TEXT NOT NULL DEFAULT 'abierto', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), last_message_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_ap_chats_user ON ap_chats(user_id, last_message_at DESC);
CREATE INDEX IF NOT EXISTS idx_ap_chats_session ON ap_chats(session_id);
CREATE TABLE IF NOT EXISTS ap_messages (id SERIAL PRIMARY KEY, chat_id INTEGER NOT NULL REFERENCES ap_chats(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT, tool_name TEXT, tool_input JSONB, tool_output JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_ap_messages_chat ON ap_messages(chat_id, created_at);
CREATE TABLE IF NOT EXISTS ap_token_usage (id SERIAL PRIMARY KEY, chat_id INTEGER REFERENCES ap_chats(id) ON DELETE SET NULL, user_id INTEGER NOT NULL REFERENCES ap_users(id), skill_id INTEGER NOT NULL REFERENCES ap_skills(id), modelo TEXT NOT NULL, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, cache_creation_tokens INTEGER NOT NULL DEFAULT 0, cache_read_tokens INTEGER NOT NULL DEFAULT 0, cost_usd NUMERIC(10,6) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_ap_token_usage_user_time ON ap_token_usage(user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_ap_token_usage_skill_time ON ap_token_usage(skill_id, created_at);
CREATE TABLE IF NOT EXISTS ap_files (id SERIAL PRIMARY KEY, chat_id INTEGER NOT NULL REFERENCES ap_chats(id) ON DELETE CASCADE, direccion TEXT NOT NULL, tipo TEXT NOT NULL, nombre_original TEXT NOT NULL, storage_path TEXT NOT NULL, size_bytes INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_ap_files_chat ON ap_files(chat_id);
CREATE OR REPLACE VIEW ap_uso_semanal_por_usuario AS SELECT u.id AS user_id, u.nombre, u.email, DATE_TRUNC('week', t.created_at) AS semana, s.nombre AS skill, COUNT(*) AS llamadas, SUM(t.input_tokens) AS input_tokens, SUM(t.output_tokens) AS output_tokens, SUM(t.cache_read_tokens) AS cache_read, ROUND(SUM(t.cost_usd)::numeric, 4) AS costo_usd FROM ap_token_usage t JOIN ap_users u ON u.id = t.user_id JOIN ap_skills s ON s.id = t.skill_id GROUP BY u.id, u.nombre, u.email, DATE_TRUNC('week', t.created_at), s.nombre ORDER BY semana DESC, costo_usd DESC;
CREATE OR REPLACE VIEW ap_uso_mensual_por_usuario AS SELECT u.id AS user_id, u.nombre, u.email, DATE_TRUNC('month', t.created_at) AS mes, s.nombre AS skill, COUNT(*) AS llamadas, SUM(t.input_tokens + t.output_tokens) AS tokens_totales, ROUND(SUM(t.cost_usd)::numeric, 4) AS costo_usd FROM ap_token_usage t JOIN ap_users u ON u.id = t.user_id JOIN ap_skills s ON s.id = t.skill_id GROUP BY u.id, u.nombre, u.email, DATE_TRUNC('month', t.created_at), s.nombre ORDER BY mes DESC, costo_usd DESC;
CREATE OR REPLACE VIEW ap_resumen_mes_actual AS SELECT s.nombre AS skill, COUNT(DISTINCT t.chat_id) AS chats, COUNT(*) AS llamadas, SUM(t.input_tokens + t.output_tokens) AS tokens_totales, ROUND(SUM(t.cost_usd)::numeric, 2) AS costo_usd FROM ap_token_usage t JOIN ap_skills s ON s.id = t.skill_id WHERE DATE_TRUNC('month', t.created_at) = DATE_TRUNC('month', NOW()) GROUP BY s.nombre ORDER BY costo_usd DESC;
